function detectLang(q: string): 'sw' | 'en' {
  const low = q.toLowerCase()
  const swWords = ['nani','alitengeza','nipe','tafadhali','nitafutie','pesa','namna','jinsi','vipi','nini','wapi','lini','kwanini','nataka','naomba','andika','sema','eleza','niandikie','ujumbe','mapenzi','mji mkuu','rais','tajiri','tengeneza','unda','nifundishe','nisaidie','habari','mambo','salamu','asante','karibu','samahani','kipi','gani','yupi','kazi','biashara','fedha','chakula','nyumba','leo','kesho','jana','sasa','hapa','kule','kwangu','kwako','yangu','yake','sisi','nyinyi','wao','mimi','wewe','yeye','hii','hiyo','ile','na','ya','za','wa','kwa','katika','kutoka','hadi','bila','pamoja','kama','lakini','kwa sababu','ili','ambayo']
  for (const w of swWords) { if (low.includes(w)) return 'sw' }
  return 'en'
}
