function cap(t: string) { if (!t) return null; const p = t.split(/((?:#|@)[\wÀ-ÿ]+)/g); return <span style={{ fontSize: 11 }}>{p.map((x, i) => x.startsWith('#') ? <span key={i} style={{ color: TEAL, fontWeight: 'bold' }}>{x} </span> : x.startsWith('@') ? <span key={i} style={{ color: '#FFD700', fontWeight: 'bold', background: 'rgba(255,215,0,0.15)', padding: '0 4px', borderRadius: 6 }}>{x} </span> : <span key={i}>{x}</span>)}</span> }

